def is_metric(points, d):
    """True if d obeys the three metric axioms on the list points."""
    for x in points:
        for y in points:
            if d(x, y) < 0 or (d(x, y) == 0) != (x == y):
                return False        # positivity, zero only on the diagonal
            if d(x, y) != d(y, x):
                return False        # symmetry
            for z in points:
                if d(x, z) > d(x, y) + d(y, z):
                    return False    # triangle inequality
    return True
